N=18; cutr=9; cutc=8
out=[[1]*N for _ in range(N)]
# cross as 2 unless source 7
for r in range(N):
 for c in range(N):
  if r==cutr or c==cutc:
   out[r][c]=7 if grid[r][c]==7 else 2
# quadrant group each toward respective corner
for top in [True,False]:
 for left in [True,False]:
  cells=[(r,c) for r in range(N) for c in range(N) if grid[r][c]==7 and (r<cutr if top else r>cutr) and (c<cutc if left else c>cutc)]
  if not cells: continue
  minr=min(r for r,c in cells); maxr=max(r for r,c in cells); minc=min(c for r,c in cells); maxc=max(c for r,c in cells)
  dr=(-minr if top else N-1-maxr)
  dc=(-minc if left else N-1-maxc)
  print('quad',top,left,'bbox',(minr,maxr,minc,maxc),'shift',dr,dc,'cells',len(cells))
  for r,c in cells:
   rr,cc=r+dr,c+dc
   out[rr][cc]=7
print('\n'.join(' '.join(map(str,row)) for row in out))
